corrected_code:
@Controller('hr/payroll')
@UseGuards(JwtAuthGuard)
export class PayrollDocumentController {
  @Get(':documentId/pdf')
  async downloadTaxForm(@Param('documentId') documentId: string, @Req() req: Request, @Res() res: Response) {
    const doc = await PayrollDocumentModel.findOne({ _id: documentId, employeeId: req.user.employeeId });
    if (!doc) return res.status(403).send('Forbidden: unauthorized access to tax document');
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Content-Disposition', `attachment; filename="${doc.filename}"`);
    fs.createReadStream(doc.storagePath).pipe(res);
  }
}
